# (чтение) новые документы 24–25.10: проведены ли, какой счёт, движения ДС
acc = q('ВЫБРАТЬ Б.Ссылка КАК С ИЗ Справочник.БанковскиеСчетаОрганизаций КАК Б ГДЕ Б.Наименование = "2209 в АО ""Народный Банк Казахстана"" KZT"')[0]['С']
for doc in ('ПоступлениеБезналичныхДенежныхСредств', 'СписаниеБезналичныхДенежныхСредств'):
    for r in q(f'ВЫБРАТЬ Д.Ссылка КАК С, Д.Дата КАК Дт, Д.Проведен КАК П, Д.БанковскийСчет КАК Б, Д.СуммаДокумента КАК Сум ИЗ Документ.{doc} КАК Д ГДЕ Д.Комментарий ПОДОБНО "%банк 24-25.10%"'):
        mv = q('ВЫБРАТЬ СУММА(Т.Сумма) КАК С ИЗ РегистрНакопления.ДенежныеСредстваБезналичные КАК Т ГДЕ Т.Регистратор = &Р', Р=r['С'])[0]['С']
        print(f"  {s(r['С'])[:60]} | {str(r['Дт'])[:16]} | пров {r['П']} | {s(r['Б'])[:30]} | {float(r['Сум']):>12,.2f} | движ.ДС {mv}")
print('ДС остаток сейчас:', q('ВЫБРАТЬ СУММА(О.СуммаОстаток) КАК С ИЗ РегистрНакопления.ДенежныеСредстваБезналичные.Остатки(, БанковскийСчет = &Б) КАК О', Б=acc)[0]['С'])
print('ДС остаток на 26.10 00:00:', q('ВЫБРАТЬ СУММА(О.СуммаОстаток) КАК С ИЗ РегистрНакопления.ДенежныеСредстваБезналичные.Остатки(&Д, БанковскийСчет = &Б) КАК О', Б=acc, Д=datetime.datetime(2026, 10, 26, 5, 0))[0]['С'])
